#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OpType {
    Add,
    Multiply,
    LogicalAnd,
    LogicalOr,
}

fn ufunc_identity(op: OpType) -> Option<i8> {
    match op {
        OpType::Add => Some(0),
        OpType::Multiply => Some(1),
        OpType::LogicalAnd | OpType::LogicalOr => None,
    }
}

// -- Optional tests --
#[cfg(test)]
mod tests {
    use super::*;

    fn logical_and(x: i8, y: i8) -> i8 {
        if x != 0 && y != 0 { 1 } else { 0 }
    }

    fn logical_or(x: i8, y: i8) -> i8 {
        if x != 0 || y != 0 { 1 } else { 0 }
    }

    #[test]
    fn test_add_identity() {
        let id = ufunc_identity(OpType::Add).unwrap();
        for x in -3..=3 {
            assert_eq!(x + id, x);
            assert_eq!(id + x, x);
        }
    }

    #[test]
    fn test_mul_identity() {
        let id = ufunc_identity(OpType::Multiply).unwrap();
        for x in -3..=3 {
            assert_eq!(x * id, x);
            assert_eq!(id * x, x);
        }
    }

    #[test]
    fn test_logical_and_no_identity() {
        assert_eq!(ufunc_identity(OpType::LogicalAnd), None);
        // We can also spot-check that no candidate works for all x
        // e.g., 0 fails (true & false -> 0 != 1), 1 fails (2 & 1 -> 1 != 2)
        assert_ne!(logical_and(1, 0), 1);
        assert_ne!(logical_and(2, 1), 2);
    }

    #[test]
    fn test_logical_or_no_identity() {
        assert_eq!(ufunc_identity(OpType::LogicalOr), None);
        // Spot-check e.g., 0 fails (true | false -> 1 != 2), 1 fails (0 | 1 -> 1 != 0)
        assert_ne!(logical_or(2, 0), 2);
        assert_ne!(logical_or(0, 1), 0);
    }
}